import subprocess
import ftplib
import os
from urllib.parse import quote


def task_func(ftp_server='ftp.dlptest.com', ftp_user='dlpuser',
              ftp_password='rNrKYTX9g7z3RgJRmxWuGHbeu', ftp_dir='/ftp/test'):
    ftp = ftplib.FTP()

    try:
        try:
            ftp.connect(ftp_server)
        except Exception as e:
            raise Exception(
                f"Failed to connect to FTP server {ftp_server}: {e}"
            ) from e

        try:
            ftp.login(ftp_user, ftp_password)
        except Exception as e:
            raise Exception(
                f"Failed to log into FTP server {ftp_server} "
                f"with user {ftp_user}: {e}"
            ) from e

        try:
            ftp.cwd(ftp_dir)
        except Exception as e:
            raise Exception(
                f"Failed to change to directory {ftp_dir} "
                f"on server {ftp_server}: {e}"
            ) from e

        filenames = [
            os.path.basename(name.rstrip('/'))
            for name in ftp.nlst()
        ]
    finally:
        ftp.close()

    attempted = []
    directory_path = quote(ftp_dir.rstrip('/'), safe='/')

    for filename in filenames:
        # An absolute FTP path needs two slashes after the hostname.
        url = (
            f"ftp://{ftp_server}/{directory_path}/"
            f"{quote(filename, safe='')}"
        )
        attempted.append(filename)
        subprocess.run(
            [
                'wget',
                f'--ftp-user={ftp_user}',
                f'--ftp-password={ftp_password}',
                '--',
                url,
            ],
            check=True,
        )

    return attempted
