from flask import Flask, render_template, redirect, url_for
from flask_login import LoginManager, UserMixin, login_user, login_required, logout_user, current_user
from flask_wtf import FlaskForm
from wtforms import StringField, PasswordField, SubmitField
from wtforms.validators import DataRequired, Length
from werkzeug.security import generate_password_hash, check_password_hash


class LoginForm(FlaskForm):
    username = StringField('Username', validators=[DataRequired(), Length(min=4, max=25)])
    password = PasswordField('Password', validators=[DataRequired(), Length(min=8, max=80)])
    submit = SubmitField('Log In')


login_manager = LoginManager()


def task_func(secret_key, template_folder):
    import os

    from flask import flash, request
    from jinja2 import ChoiceLoader, DictLoader

    if not secret_key:
        raise ValueError("A secret_key is required")

    app = Flask(__name__, template_folder=template_folder)
    app.config["SECRET_KEY"] = secret_key

    # Files in template_folder take precedence over these built-in templates.
    app.jinja_loader = ChoiceLoader([
        app.jinja_loader,
        DictLoader({
            "login.html": """
                <!doctype html>
                <title>Log in</title>
                <h1>Log in</h1>
                {% with messages = get_flashed_messages() %}
                  {% for message in messages %}<p>{{ message }}</p>{% endfor %}
                {% endwith %}
                <form method="post">
                  {{ form.hidden_tag() }}
                  <p>{{ form.username.label }} {{ form.username() }}</p>
                  <p>{{ form.password.label }} {{ form.password() }}</p>
                  {% for field in (form.username, form.password) %}
                    {% for error in field.errors %}<p>{{ error }}</p>{% endfor %}
                  {% endfor %}
                  {{ form.submit() }}
                </form>
            """,
            "protected.html": """
                <!doctype html>
                <title>Protected page</title>
                <h1>Welcome, {{ user.username }}</h1>
                <form method="post" action="{{ url_for('logout') }}">
                  {{ logout_form.hidden_tag() }}
                  {{ logout_form.submit() }}
                </form>
            """,
        }),
    ])

    class User(UserMixin):
        def __init__(self, username, password_hash):
            self.id = username
            self.username = username
            self.password_hash = password_hash

    class LogoutForm(FlaskForm):
        submit = SubmitField("Log Out")

    # Set APP_USERNAME and either APP_PASSWORD_HASH or APP_PASSWORD in the
    # environment. No account or default password is created implicitly.
    username = os.environ.get("APP_USERNAME")
    password_hash = os.environ.get("APP_PASSWORD_HASH")
    if not password_hash and os.environ.get("APP_PASSWORD"):
        password_hash = generate_password_hash(os.environ["APP_PASSWORD"])

    users = {}
    if username and password_hash:
        users[username] = User(username, password_hash)

    login_manager.init_app(app)
    login_manager.login_view = "login"

    @login_manager.user_loader
    def load_user(user_id):
        return users.get(user_id)

    @app.route("/")
    def index():
        return redirect(url_for("protected"))

    @app.route("/login", methods=["GET", "POST"])
    def login():
        if current_user.is_authenticated:
            return redirect(url_for("protected"))

        form = LoginForm()
        if form.validate_on_submit():
            user = users.get(form.username.data)
            if user and check_password_hash(user.password_hash, form.password.data):
                login_user(user)
                return redirect(url_for("protected"))
            flash("Invalid username or password.")

        return render_template("login.html", form=form)

    @app.route("/protected")
    @login_required
    def protected():
        return render_template(
            "protected.html",
            user=current_user,
            logout_form=LogoutForm(),
        )

    @app.route("/logout", methods=["POST"])
    @login_required
    def logout():
        form = LogoutForm()
        if not form.validate_on_submit():
            return "Invalid logout request", 400
        logout_user()
        return redirect(url_for("login"))

    return app
