import pandas as pd
import matplotlib.pyplot as plt
from statsmodels.tsa.seasonal import seasonal_decompose


def task_func(df, freq='D', decomposition_model='multiplicative'):
    """Decompose the 'value' column into trend, seasonality, and residuals."""
    if not isinstance(df, pd.DataFrame):
        raise ValueError("'df' must be a pandas DataFrame.")
    if not {'date', 'value'}.issubset(df.columns):
        raise ValueError("'df' must contain 'date' and 'value' columns.")
    if decomposition_model not in ('additive', 'multiplicative'):
        raise ValueError(
            "'decomposition_model' must be 'additive' or 'multiplicative'."
        )
    if not isinstance(freq, str):
        raise ValueError("'freq' must be a valid frequency string.")

    try:
        offset = pd.tseries.frequencies.to_offset(freq)
    except (TypeError, ValueError) as exc:
        raise ValueError("'freq' must be a valid frequency string.") from exc

    values = df['value']
    if (
        not pd.api.types.is_numeric_dtype(values)
        or pd.api.types.is_bool_dtype(values)
        or pd.api.types.is_complex_dtype(values)
        or values.isna().any()
    ):
        raise ValueError("'value' must contain non-missing, real numeric data.")

    try:
        numeric_values = values.astype(float)
    except (TypeError, ValueError, OverflowError) as exc:
        raise ValueError("'value' must contain valid numeric data.") from exc
    if not numeric_values.map(lambda value: float('-inf') < value < float('inf')).all():
        raise ValueError("'value' must contain only finite numbers.")

    try:
        dates = pd.to_datetime(df['date'], errors='raise')
    except (TypeError, ValueError) as exc:
        raise ValueError("'date' must contain valid dates.") from exc
    if dates.isna().any():
        raise ValueError("'date' must not contain missing dates.")

    series = pd.Series(
        numeric_values.to_numpy(),
        index=pd.DatetimeIndex(dates),
        name='value',
    ).sort_index()
    if series.index.has_duplicates:
        raise ValueError("'date' must not contain duplicate dates.")

    series = series.asfreq(offset)
    if series.isna().any():
        raise ValueError("The dates must form a complete series at 'freq'.")
    if decomposition_model == 'multiplicative' and (series <= 0).any():
        raise ValueError("Multiplicative decomposition requires positive values.")

    result = seasonal_decompose(series, model=decomposition_model)
    figure = result.plot()
    return result, figure.axes[0]
