import socket
from ipaddress import IPv4Network
from threading import Thread

def task_func(ip_range, port):
    from threading import Lock

    network = IPv4Network(ip_range, strict=False)
    addresses = iter(network.hosts())
    results = {}
    address_lock = Lock()
    result_lock = Lock()

    def scan():
        while True:
            with address_lock:
                try:
                    ip = next(addresses)
                except StopIteration:
                    return

            try:
                with socket.socket(socket.AF_INET, socket.SOCK_STREAM) as sock:
                    sock.settimeout(1.0)
                    is_open = sock.connect_ex((str(ip), port)) == 0
            except OSError:
                is_open = False

            with result_lock:
                results[str(ip)] = is_open

    address_count = (
        network.num_addresses
        if network.prefixlen >= 31
        else network.num_addresses - 2
    )
    threads = [Thread(target=scan) for _ in range(min(100, address_count))]

    for thread in threads:
        thread.start()
    for thread in threads:
        thread.join()

    return results

