def task_func(log_file):
    from pathlib import Path

    pattern = re.compile(r"^([A-Za-z]+): \[(.*?)\] - (.*)$")
    timestamp_format = re.compile(r"\d{4}-\d{2}-\d{2} \d{2}:\d{2}:\d{2}")
    entries = []

    with open(log_file, "r", encoding="utf-8") as file:
        for line in file:
            match = pattern.fullmatch(line.rstrip("\r\n"))
            if not match:
                continue

            message_type, timestamp, message = match.groups()
            if not timestamp_format.fullmatch(timestamp):
                raise ValueError(f"Invalid timestamp: {timestamp}")

            try:
                datetime.strptime(timestamp, "%Y-%m-%d %H:%M:%S")
            except ValueError as exc:
                raise ValueError(f"Invalid timestamp: {timestamp}") from exc

            entries.append((message_type, timestamp, message))

    if not entries:
        raise ValueError("No valid log entries found")

    source = Path(log_file)
    output = source.with_suffix(".csv")
    if output == source:
        output = source.with_name(f"{source.stem}_structured.csv")

    pd.DataFrame(
        entries, columns=["Type", "Timestamp", "Message"]
    ).to_csv(output, index=False)

    return str(output)
