import re
import nltk
from string import punctuation


def task_func(df):
    """Count words in articles whose titles contain 'like' or 'what'."""
    required_columns = {"Title", "Content"}
    if df.empty or not required_columns.issubset(df.columns):
        raise ValueError("DataFrame must be non-empty and contain 'Title' and 'Content' columns.")

    matching_titles = df["Title"].str.contains(r"like|what", case=False, na=False)
    frequencies = nltk.FreqDist()

    for content in df.loc[matching_titles, "Content"].dropna():
        # Match Unicode letters and digits while excluding punctuation, including underscores.
        frequencies.update(re.findall(r"[^\W_]+", str(content).lower()))

    return dict(frequencies)
