import pandas as pd
import pytz
from datetime import datetime
from random import randint, seed as set_seed


def task_func(
    utc_datetime,
    cities=['New York', 'London', 'Beijing', 'Tokyo', 'Sydney'],
    weather_conditions=['Sunny', 'Cloudy', 'Rainy', 'Snowy', 'Stormy'],
    timezones={
        'New York': 'America/New_York',
        'London': 'Europe/London',
        'Beijing': 'Asia/Shanghai',
        'Tokyo': 'Asia/Tokyo',
        'Sydney': 'Australia/Sydney'
    },
    seed=42
):
    if not isinstance(utc_datetime, datetime):
        raise ValueError("utc_datetime must be a datetime object.")

    if not isinstance(cities, list) or any(
        not isinstance(city, str) or not city for city in cities
    ):
        raise ValueError("cities must be a list of non-empty strings.")

    if not isinstance(weather_conditions, list) or not weather_conditions or any(
        not isinstance(condition, str) or not condition
        for condition in weather_conditions
    ):
        raise ValueError("weather_conditions must be a non-empty list of non-empty strings.")

    if not isinstance(timezones, dict) or any(
        not isinstance(city, str) or not city
        or not isinstance(zone, str) or not zone
        for city, zone in timezones.items()
    ):
        raise ValueError("timezones must map city names to timezone strings.")

    if not isinstance(seed, int) or isinstance(seed, bool):
        raise ValueError("seed must be an integer.")

    if any(city not in timezones for city in cities):
        raise ValueError("Every city must have a timezone.")

    try:
        zones = {city: pytz.timezone(zone) for city, zone in timezones.items()}
    except pytz.UnknownTimeZoneError as exc:
        raise ValueError("timezones contains an invalid timezone.") from exc

    if utc_datetime.tzinfo is None:
        utc_time = pytz.utc.localize(utc_datetime)
    else:
        utc_time = utc_datetime.astimezone(pytz.utc)

    set_seed(seed)
    rows = []
    for city in cities:
        local_time = utc_time.astimezone(zones[city])
        rows.append({
            'City': city,
            'Local Time': local_time.strftime('%Y-%m-%d %H:%M:%S %Z'),
            'Weather Condition': weather_conditions[
                randint(0, len(weather_conditions) - 1)
            ]
        })

    return pd.DataFrame(
        rows,
        columns=['City', 'Local Time', 'Weather Condition']
    )
