import json

SUCCESS_RESPONSE = {
    'status': 'success',
    'message': 'Data received successfully.'
}
ERROR_RESPONSE = {
    'status': 'error',
    'message': 'Invalid data received.'
}


def task_func():
    class PostRequestHandler(http.server.BaseHTTPRequestHandler):
        def _send_json(self, status_code, response):
            body = json.dumps(response).encode('utf-8')
            self.send_response(status_code)
            self.send_header('Content-Type', 'application/json')
            self.send_header('Content-Length', str(len(body)))
            self.end_headers()
            self.wfile.write(body)

        def _send_error_response(self, message):
            response = {**ERROR_RESPONSE, 'message': message}
            self._send_json(400, response)

        def do_POST(self):
            content_type, _ = cgi.parse_header(
                self.headers.get('Content-Type', '')
            )
            if content_type.lower() != 'application/json':
                self._send_error_response(
                    'Content-Type header is not application/json'
                )
                return

            try:
                content_length = int(self.headers.get('Content-Length', '0'))
                if content_length < 0:
                    raise ValueError('Negative content length')
                data = json.loads(self.rfile.read(content_length))
            except (ValueError, UnicodeDecodeError):
                self._send_error_response('Invalid JSON')
                return

            if not isinstance(data, dict) or 'data' not in data:
                self._send_error_response('No data key in request')
                return

            self._send_json(200, SUCCESS_RESPONSE)

    return PostRequestHandler
