            self.send_header("Content-Length", str(len(body)))
            self.end_headers()
            self.wfile.write(body)

        def do_POST(self):
            # Also allow the handler to be exercised without a socket-backed
            # BaseHTTPRequestHandler initialization.
            if not hasattr(self, "request_version"):
                self.request_version = "HTTP/1.1"
            if not hasattr(self, "_headers_buffer"):
                self._headers_buffer = []
            if not hasattr(self, "wfile"):
                from io import BytesIO
                self.wfile = BytesIO()

            try:
                content_type, _ = cgi.parse_header(
                    self.headers.get("Content-Type", "")
                )
                if content_type.lower() != "application/json":
                    raise ValueError("Content-Type must be application/json")

                length = int(self.headers.get("Content-Length", ""))
                if length < 0:
                    raise ValueError("Invalid Content-Length")

                data = json.loads(self.rfile.read(length).decode("utf-8"))
                if not isinstance(data, dict):
                    raise ValueError("Email data must be a JSON object")

                for key in ("subject", "message", "to"):
                    if key not in data:
                        raise ValueError(f"Missing required key: {key}")
                    if not isinstance(data[key], str):
                        raise ValueError(f"{key} must be a string")

                email = MIMEText(data["message"], "plain", "utf-8")
                email["Subject"] = data["subject"]
                email["From"] = smtp_username
                email["To"] = data["to"]

                with smtplib.SMTP(smtp_server, smtp_port) as smtp:
                    smtp.login(smtp_username, smtp_password)
                    smtp.sendmail(
                        smtp_username, [data["to"]], email.as_string()
                    )

            except (json.JSONDecodeError, UnicodeDecodeError, ValueError) as exc:
                self.send_text_response(400, str(exc), "Bad Request")
            except smtplib.SMTPAuthenticationError:
                self.send_text_response(
                    535, "Authentication Failed", "Authentication Failed"
                )
            else:
                self.send_text_response(200, "Email sent successfully")

    return EmailHandler

