import re
import os
import shutil
from datetime import datetime

def task_func(directory):
    moved_files = {}

    for entry in sorted(os.scandir(directory), key=lambda item: item.name):
        if not entry.is_file():
            continue

        stem, extension = os.path.splitext(entry.name)
        depth = 0
        folder_name = None

        for token in re.findall(r"\[|\]|[^\[\]]+", stem):
            if token == "[":
                depth += 1
            elif token == "]":
                depth = max(0, depth - 1)
            elif depth == 0 and token.strip():
                folder_name = token.strip()
                break

        if not folder_name or folder_name in {".", ".."}:
            continue

        destination_dir = os.path.join(directory, folder_name)
        if os.path.lexists(destination_dir) and not os.path.isdir(destination_dir):
            continue

        os.makedirs(destination_dir, exist_ok=True)

        destination_name = entry.name
        destination = os.path.join(destination_dir, destination_name)
        counter = 1

        while os.path.lexists(destination):
            destination_name = f"{stem}_{counter}{extension}"
            destination = os.path.join(destination_dir, destination_name)
            counter += 1

        shutil.move(entry.path, destination)
        moved_files.setdefault(folder_name, []).append(destination_name)

    return directory, moved_files

