                "filename": "file2.xlsx",
                "sheets": {
                    "Sheet1": [
                        ["Just a", "Normal row.", "Nothing special."],
                        ["Another", "normal row.", "Still nothing special."]
                    ],
                    "Sheet2": [
                        ["Sheet2 data.", "Another \"quoted\" string.", "End of row."]
                    ]
                }
            },
            {
                "filename": "file3.xlsx",
                "sheets": {
                    "Sheet1": [
                        ["A simple", "row without", "any quotes."]
                    ]
                }
            }
        ]
        # Create the Excel files based on the mock data
