                         'This is a \\"test\\" string.')
        self.assertEqual(sheet.cell(row=2, column=2).value, 'Row with \\"quotes\\"')
        self.assertEqual(sheet.cell(row=2, column=3).value, 'And \\"more\\" quotes.')
